import{_ as e,o as t,c as s,a0 as n}from"./chunks/framework.CShDTZbC.js";const h=JSON.parse('{"title":"Export","description":"","frontmatter":{},"headers":[],"relativePath":"syntax/export.md","filePath":"syntax/export.md"}'),o={name:"syntax/export.md"};function p(r,a,i,d,l,c){return t(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h1><p>Export deklarasi dari file agar bisa di-import oleh file lain.</p><h2 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;Syntax&quot;">​</a></h2><h3 id="_1-selective-export-—-export-a-b-from-path" tabindex="-1">1. Selective Export — <code>export a, b from ./path</code> <a class="header-anchor" href="#_1-selective-export-—-export-a-b-from-path" aria-label="Permalink to &quot;1. Selective Export — \`export a, b from ./path\`&quot;">​</a></h3><p>Mengekspor item tertentu dari module lain:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// file modules/math.rp</span></span>
<span class="line"><span>add(a, b) { return a + b }</span></span>
<span class="line"><span>sub(a, b) { return a - b }</span></span>
<span class="line"><span>mul(a, b) { return a * b }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// file index.rp — hanya export add dan sub</span></span>
<span class="line"><span>export add, sub from ./math</span></span></code></pre></div><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import add, sub from ./index</span></span>
<span class="line"><span>print(add(2, 3))  // 5</span></span>
<span class="line"><span>print(sub(5, 2))  // 3</span></span>
<span class="line"><span>// mul tidak bisa di-import — tidak di-export</span></span></code></pre></div><h3 id="_2-namespace-export-—-export-name-from-path" tabindex="-1">2. Namespace Export — <code>export name from ./path</code> <a class="header-anchor" href="#_2-namespace-export-—-export-name-from-path" aria-label="Permalink to &quot;2. Namespace Export — \`export name from ./path\`&quot;">​</a></h3><p>Mengekspor seluruh module sebagai namespace dengan nama custom:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// file modules/math.rp</span></span>
<span class="line"><span>add(a, b) { return a + b }</span></span>
<span class="line"><span>sub(a, b) { return a - b }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// file index.rp</span></span>
<span class="line"><span>export math_utils from ./math</span></span></code></pre></div><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import math_utils from ./index</span></span>
<span class="line"><span>print(math_utils.add(2, 3))  // 5</span></span>
<span class="line"><span>print(math_utils.sub(5, 2))  // 3</span></span></code></pre></div><blockquote><p>Nama namespace (<code>math_utils</code>) tidak harus sama dengan nama file (<code>math.rp</code>).</p></blockquote><h3 id="_3-policy-export-—-export-name-from-path-item-private" tabindex="-1">3. Policy Export — <code>export name from ./path -&gt; { item: private }</code> <a class="header-anchor" href="#_3-policy-export-—-export-name-from-path-item-private" aria-label="Permalink to &quot;3. Policy Export — \`export name from ./path -&gt; { item: private }\`&quot;">​</a></h3><p>Mengekspor module dengan akses kontrol item tertentu:</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// file modules/auth.rp</span></span>
<span class="line"><span>login(user, pass) { ... }</span></span>
<span class="line"><span>register(user, pass) { ... }</span></span>
<span class="line"><span>hashPassword(pass) { ... }   // internal — tidak boleh diakses luar</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// file index.rp</span></span>
<span class="line"><span>export auth from ./auth -&gt; { hashPassword: private }</span></span></code></pre></div><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import auth from ./index</span></span>
<span class="line"><span>auth.login(&quot;admin&quot;, &quot;123&quot;)      // ✅ works</span></span>
<span class="line"><span>auth.register(&quot;user&quot;, &quot;456&quot;)    // ✅ works</span></span>
<span class="line"><span>auth.hashPassword(&quot;secret&quot;)     // ❌ PrivateError: &#39;hashPassword&#39; is private and cannot be called from outside</span></span></code></pre></div><h2 id="aturan" tabindex="-1">Aturan <a class="header-anchor" href="#aturan" aria-label="Permalink to &quot;Aturan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Syntax</th><th>Keterangan</th></tr></thead><tbody><tr><td><code>export a, b from ./c</code></td><td>Hanya <code>a</code> dan <code>b</code> yang di-export dari <code>c</code></td></tr><tr><td><code>export c from ./c</code></td><td>Seluruh binding di <code>c</code> di-export sebagai namespace <code>c</code></td></tr><tr><td><code>export c from ./c -&gt; { x: private }</code></td><td>Namespace <code>c</code> di-export, tapi <code>x</code> tidak bisa diakses</td></tr><tr><td><code>export math</code></td><td>Legacy — export semua binding (backward compatible)</td></tr></tbody></table><h3 id="behavior-detail" tabindex="-1">Behavior Detail <a class="header-anchor" href="#behavior-detail" aria-label="Permalink to &quot;Behavior Detail&quot;">​</a></h3><ul><li><strong>Source module tidak perlu punya <code>export</code> statement</strong> sendiri. Export dideklarasikan di file yang melakukan import (<code>index.rp</code>).</li><li><strong>Private items</strong> tidak bisa dipanggil dari luar. Jika dipanggil, muncul <code>PrivateError</code> yang spesifik.</li><li><strong><code>_private</code> metadata</strong> disimpan secara internal di module object dan tidak ditampilkan saat <code>print()</code>.</li></ul><h2 id="error-cases" tabindex="-1">Error Cases <a class="header-anchor" href="#error-cases" aria-label="Permalink to &quot;Error Cases&quot;">​</a></h2><ul><li><strong>Module tanpa export</strong>: Jika file tidak memiliki <code>export</code>, nothing is exported (return <code>null</code>).</li><li><strong>Import private item</strong>: Jika mencoba memanggil item yang di-mark <code>private</code>, muncul <code>PrivateError: &#39;&lt;name&gt;&#39; is private and cannot be called from outside</code>.</li><li><strong>Import dari module kosong</strong>: Jika module tidak export apapun, import akan error.</li></ul><h2 id="path-resolution" tabindex="-1">Path Resolution <a class="header-anchor" href="#path-resolution" aria-label="Permalink to &quot;Path Resolution&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Resolves to</th></tr></thead><tbody><tr><td><code>./modules.a</code></td><td><code>./modules/a.rp</code></td></tr><tr><td><code>./modules</code></td><td><code>./modules/*.rp</code></td></tr><tr><td><code>rupa</code></td><td>stdlib module</td></tr></tbody></table>`,24)])])}const m=e(o,[["render",p]]);export{h as __pageData,m as default};
